{"file_path":"/work/tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate, conversion_rate_by_group, conversions_in_window,
    longest_conversion_streak, pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_unconverted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "c": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (2, 5), (5, 6)])
def test_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_parse_skips_comments_and_blank_lines_and_strips_fields():
    assert parse_session_log(["", "  \t", "  # comment", " a , 1 , 0 ", "b,2, "]) == [
        {"id": "a", "day": 1, "converted": False},
        {"id": "b", "day": 2, "converted": None},
    ]


@pytest.mark.parametrize("line", ["x,1", "x,1,0,extra", "x,no,1"])
def test_parse_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", "", "ok,1,1", line])


def test_dedupe_keeps_last_record_even_if_it_has_an_earlier_day():
    events = parse_session_log(["a,5,0", "b,2,0", "c,1,1", "a,2,1"])
    assert dedupe_sessions(events) == [events[2], events[3], events[1]]


def test_daily_counts_include_gaps_and_ignore_outside_sessions():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_session_log(["x,1,1", "y,4,0"]), "b": parse_session_log(["z,1,"]), "c": []}
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"converted": False}], "b": [{"converted": True}], "a": [{"converted": True}], "c": []}
    assert top_converting_groups(groups, 4) == ["a", "b", "z"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("c", None), ("z", 0.0)]


@pytest.mark.parametrize("counts,expected", [([], 0), ([-1, 0], 0), ([1, 0, 1, 2, -1, 2], 2)])
def test_longest_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
